<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; Security::requireRole(['administrador','gerente']);$msg=null;if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$s=db()->prepare('INSERT INTO pagamentos(pedido_id,data_pagamento,valor,forma_pagamento,observacao) VALUES(?,?,?,?,?)');$s->execute([(int)$_POST['pedido_id'],$_POST['data_pagamento']?:date('Y-m-d'),max(0,(float)$_POST['valor']),trim($_POST['forma_pagamento']),trim($_POST['observacao']??'')]);Audit::log('Baixa de pagamento','pagamentos',(int)db()->lastInsertId());$msg='Pagamento registrado.';}$pedidos=db()->query("SELECT id,valor FROM pedidos WHERE status<>'cancelado' ORDER BY id DESC LIMIT 100")->fetchAll();$rows=db()->query('SELECT p.*,r.cliente_id FROM pagamentos p JOIN pedidos r ON r.id=p.pedido_id ORDER BY p.id DESC LIMIT 100')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagamentos</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h1>Contas a receber</h1><a href="dashboard.php">← Dashboard</a><?php if($msg):?><div class="alert alert-success mt-3"><?=Security::e($msg)?></div><?php endif;?><div class="card p-3 my-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-3"><select class="form-select" name="pedido_id" required><option value="">Pedido</option><?php foreach($pedidos as $p):?><option value="<?=$p['id']?>">#<?=$p['id']?> - R$ <?=number_format($p['valor'],2,',','.')?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="data_pagamento" value="<?=date('Y-m-d')?>"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="valor" placeholder="Valor" required></div><div class="col-md-2"><input class="form-control" name="forma_pagamento" placeholder="Forma"></div><div class="col-md-2"><input class="form-control" name="observacao" placeholder="Observação"></div><div class="col-md-1"><button class="btn btn-primary">Baixar</button></div></form></div><table class="table"><thead><tr><th>ID</th><th>Pedido</th><th>Data</th><th>Valor</th><th>Forma</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td>#<?=$r['pedido_id']?></td><td><?=Security::e($r['data_pagamento'])?></td><td>R$ <?=number_format($r['valor'],2,',','.')?></td><td><?=Security::e($r['forma_pagamento'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>
